<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import {create as review} from '../api/reviews';import {create as report} from '../api/reports';import {download} from '../api/client';import {useAsync} from '../hooks/useAsync';import {date} from '../utils/format';import {DECISIONS} from '../constants/enums';const props=defineProps<{data:Workspace;canWrite:boolean;isAdmin:boolean;refresh:()=>Promise<void>}>();const completed=computed(()=>props.data.runs.filter(r=>r.status==='completed'));const id=ref(''),note=ref(''),decision=ref('accepted');const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await review({run_id:id.value||completed.value[0]?.id,note:note.value,decision:decision.value});note.value='';await props.refresh()})}async function publish(run_id:string){await execute(async()=>{await report({run_id,title:'窗口容量人工复核 · '+new Date().toISOString().slice(0,10)});await props.refresh()})};
</script><template><PageHeading code="06 / REVIEW & RELEASE" title="容量建议，连同假设一起交付。" description="分析员记录人工意见，管理员确认最新意见为接受后归档。全部角色可下载已归档重复试验CSV。"/><section class="paper" v-if="canWrite"><h2>人工容量复核</h2><form class="grid-form" @submit.prevent="submit"><label>完成的预演<select aria-label="复核运行" v-model="id"><option value="" disabled>默认使用最新完成预演</option><option v-for="r in completed" :key="r.id" :value="r.id">{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}} · {{r.created_at.slice(11,19)}}</option></select></label><label>复核判断<select v-model="decision"><option value="accepted">接受并记录假设</option><option value="needs_attention">需要继续核查</option></select></label><label class="wide">依据与假设<textarea aria-label="依据与假设" required minlength="8" rows="3" v-model="note" placeholder="请记录峰值、稳态条件、预热与模型假设的复核依据，至少8个字。"/></label><button :disabled="busy||!completed.length">提交容量复核</button></form></section><Notice v-if="error" error>{{error}}</Notice><section class="paper"><h2>复核记录</h2><Empty v-if="!data.reviews.length">运行完成后，请记录输入率、窗口数与不确定性，再提交人工复核。</Empty><article class="review-record" v-for="r in data.reviews" :key="r.id"><div><span :class="['status',r.decision]">{{DECISIONS[r.decision]}}</span><small>{{r.author}} · {{date(r.created_at)}}</small></div><p>{{r.note}}</p><button v-if="isAdmin&&r.decision==='accepted'&&!data.reports.some(p=>p.run_id===r.run_id)" class="secondary" :disabled="busy" @click="publish(r.run_id)">批准并归档</button></article></section><section class="paper"><h2>归档报告</h2><article class="report-row" v-for="p in data.reports" :key="p.id"><div><h3>{{p.title}}</h3><small>{{date(p.created_at)}} · {{p.published_by}}<template v-if="data.runs.find(r=>r.id===p.run_id)"> · 数据版本 r{{data.runs.find(r=>r.id===p.run_id)?.dataset_revision}} · 校验 {{data.runs.find(r=>r.id===p.run_id)?.profile_checksum.slice(0,12)}}</template></small></div><button class="secondary" @click="execute(()=>download(p.id))">下载CSV　↓</button></article></section><details class="audit-details"><summary>操作留痕 / 最近{{data.audit.length}}条</summary><div class="table-scroll"><table><thead><tr><th>操作者</th><th>动作</th><th>状态</th></tr></thead><tbody><tr v-for="a in data.audit" :key="a.id"><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.status}}</td></tr></tbody></table></div></details></template>
